function sameShape(s: string, t: string): boolean {
  const fwd = new Map<string, string>(), back = new Map<string, string>();
  for (let i = 0; i < s.length; i++) {
    const a = s[i], b = t[i];
    if (fwd.has(a) && fwd.get(a) !== b) return false;
    if (back.has(b) && back.get(b) !== a) return false;
    fwd.set(a, b);
    back.set(b, a);
  }
  return true;
}

